// DIAGNOSIS:
// EXPLAIN confirms full sequential scan: 85,000 rows scanned,
// 58 returned (84,942 filtered). The query filters on user_id
// and status but no index exists on these columns.
// Data growth (5K -> 85K = 17x) explains the proportional
// latency growth (180ms -> 2,100ms ≈ 11.7x).
// Non-linear because PostgreSQL query planner may have switched
// from index scan (efficient at 5K) to seq scan (its estimate
// at certain cardinalities).

// FIX:
// Composite index on (user_id, status) - both columns in the filter
CREATE INDEX CONCURRENTLY idx_orders_user_status
ON orders (user_id, status)
WHERE status IN ('shipped', 'delivered', 'pending', 'cancelled');
// CONCURRENTLY: no table lock during creation (safe for production)
// Partial index on common statuses: smaller index, faster lookups

// PREDICTED EXPLAIN AFTER FIX:
// Index Scan using idx_orders_user_status on orders
// Index Cond: ((user_id = $1) AND (status = ANY('{shipped,delivered}')))
// Rows Removed by Filter: 0 (index targets exactly what we need)
// Execution Time: ~4ms  (from 2,087ms - ~500x improvement)

// PREVENTION:
// 1. Alert threshold: p99 order history API <= 300ms
//    (was 5,000ms - far too permissive to catch gradual degradation)
// 2. Code review requirement: any new query touching the orders table
//    must include EXPLAIN ANALYZE output in the PR description
// 3. Weekly metrics review: track week-over-week p99 for all
//    customer-facing APIs in engineering standup

