import { GetSecretValueCommand, SecretsManagerClient,
         UpdateSecretCommand } from '@aws-sdk/client-secrets-manager';

class SecretsManager {
  private cache = new Map<string, { value: string; fetchedAt: Date }>();
  private client: SecretsManagerClient;
  private readonly TTL_MS = 5 * 60 * 1000; // 5-minute cache TTL

  constructor(private region: string = 'us-east-1') {
    this.client = new SecretsManagerClient({ region });
  }

  async getSecret(name: string): Promise<string> {
    const cached = this.cache.get(name);
    if (cached && Date.now() - cached.fetchedAt.getTime() < this.TTL_MS) {
      return cached.value; // return cached value if fresh
    }
    return this.fetchFromSource(name);
  }

  private async fetchFromSource(name: string): Promise<string> {
    const command = new GetSecretValueCommand({ SecretId: name });
    const response = await this.client.send(command);
    const value = response.SecretString ?? '';
    this.cache.set(name, { value, fetchedAt: new Date() });
    // NEVER log the value - only log that the secret was fetched
    console.log(`Secret '${name}' fetched and cached`);
    return value;
  }

  async refreshSecret(name: string): Promise<string> {
    this.cache.delete(name); // invalidate cache
    return this.fetchFromSource(name); // force re-fetch
  }

  async rotateAndUpdate(name: string, newValue: string): Promise<void> {
    // Update the secret in AWS Secrets Manager
    const command = new UpdateSecretCommand({
      SecretId: name,
      SecretString: newValue
    });
    await this.client.send(command);
    // Update local cache immediately
    this.cache.set(name, { value: newValue, fetchedAt: new Date() });
    console.log(`Secret '${name}' rotated and cache updated`);
  }
}

// USAGE:
const secrets = new SecretsManager();
const paymentKey = await secrets.getSecret('production/payment-api-key');
// Key is never in source code, .env files, or environment variables

