// Implement a reconciliation check that:
// 1. Counts total rows in source (production orders table)
//    and destination (fact_orders analytics table)
// 2. Sums total revenue in both
// 3. Alerts if row count differs by more than 0.1%
//    OR if total revenue differs by more than 0.5%
// 4. Returns a ReconciliationResult with details

interface ReconciliationResult {
  sourceRowCount: number;
  analyticsRowCount: number;
  rowCountDriftPct: number;
  sourceRevenue: number;
  analyticsRevenue: number;
  revenueDriftPct: number;
  isHealthy: boolean;
  alerts: string[];
}

async function runPipelineReconciliation(): Promise<ReconciliationResult> {
  // TODO: implement
}

codingChallenge.solutionExample:
async function runPipelineReconciliation(): Promise<ReconciliationResult> {
  // Query source (production)
  const [sourceRows, sourceRevenue] = await Promise.all([
    productionDb.query<{ count: string }>(
      'SELECT COUNT(*) as count FROM orders'
    ).then(r => parseInt(r.rows[0].count, 10)),
    productionDb.query<{ total: string }>(
      'SELECT COALESCE(SUM(total_amount), 0) as total FROM orders'
    ).then(r => parseFloat(r.rows[0].total))
  ]);

  // Query destination (analytics)
  const [analyticsRows, analyticsRevenue] = await Promise.all([
    analyticsDb.query<{ count: string }>(
      'SELECT COUNT(*) as count FROM fact_orders'
    ).then(r => parseInt(r.rows[0].count, 10)),
    analyticsDb.query<{ total: string }>(
      'SELECT COALESCE(SUM(total_amount), 0) as total FROM fact_orders'
    ).then(r => parseFloat(r.rows[0].total))
  ]);

  // Calculate drift percentages
  const rowCountDriftPct = sourceRows > 0
    ? Math.abs((analyticsRows - sourceRows) / sourceRows) * 100
    : 0;
  const revenueDriftPct = sourceRevenue > 0
    ? Math.abs((analyticsRevenue - sourceRevenue) / sourceRevenue) * 100
    : 0;

  // Evaluate health
  const alerts: string[] = [];
  if (rowCountDriftPct > 0.1) {
    alerts.push(
      `Row count drift: ${rowCountDriftPct.toFixed(2)}% ` +
      `(source: ${sourceRows}, analytics: ${analyticsRows})`
    );
  }
  if (revenueDriftPct > 0.5) {
    alerts.push(
      `Revenue drift: ${revenueDriftPct.toFixed(2)}% ` +
      `(source: $${sourceRevenue.toFixed(2)}, ` +
      `analytics: $${analyticsRevenue.toFixed(2)})`
    );
  }

  const result: ReconciliationResult = {
    sourceRowCount: sourceRows,
    analyticsRowCount: analyticsRows,
    rowCountDriftPct,
    sourceRevenue,
    analyticsRevenue,
    revenueDriftPct,
    isHealthy: alerts.length === 0,
    alerts
  };

  if (!result.isHealthy) {
    // Alert via Module 36's alerting infrastructure
    await alertingService.sendCritical(
      'Pipeline Reconciliation Failed',
      alerts.join('\n')
    );
    logger.error({ reconciliation: result }, 'Pipeline reconciliation failed');
  } else {
    logger.info({ reconciliation: result }, 'Pipeline reconciliation passed');
  }

  return result;
}

