// PHASE 1: DUAL WRITE implementation
// Write to both old shared DB and new Inventory DB simultaneously

class InventoryService {
  constructor(
    private oldDb: PostgresClient,    // shared DB (old)
    private inventoryDb: PostgresClient, // new Inventory DB
    private migrationFlags: FeatureFlags
  ) {}

  async updateStock(productId: string, delta: number): Promise<void> {
    // Always write to the new Inventory DB
    await this.inventoryDb.query(
      'UPDATE inventory_items SET quantity = quantity + $2 WHERE product_id = $1',
      [productId, delta]
    );

    // PHASE 1 + 2 + 3: also write to old DB (dual write for safety)
    if (!this.migrationFlags.get('inventory-migration-stop-old-writes')) {
      await this.oldDb.query(
        'UPDATE inventory_items SET quantity = quantity + $2 WHERE product_id = $1',
        [productId, delta]
      );
    }
    // PHASE 4+: only new DB written (old flag = true, old DB not written)
  }

  async getStock(productId: string): Promise<number> {
    // PHASE 1 + 2: read from OLD DB (source of truth = old DB)
    if (!this.migrationFlags.get('inventory-migration-read-new')) {
      const row = await this.oldDb.query(
        'SELECT quantity FROM inventory_items WHERE product_id = $1',
        [productId]
      );
      return row.rows[0].quantity;
    }

    // PHASE 3+: read from new Inventory DB (source of truth = new DB)
    const row = await this.inventoryDb.query(
      'SELECT quantity FROM inventory_items WHERE product_id = $1',
      [productId]
    );
    return row.rows[0].quantity;
  }
}

// PHASE TRANSITION MECHANISM: feature flags, not code deploys
// This means each phase transition is:
// 1. Verified in staging
// 2. Rolled out to 1% traffic first (canary)
// 3. Rolled back in seconds if problems appear
// 4. No code redeploy needed for rollback

// RECONCILIATION CHECK (verifies Phase 1 is working before Phase 3):
async function verifyInventoryMigration(): Promise<boolean> {
  const [oldTotal, newTotal] = await Promise.all([
    oldDb.query('SELECT SUM(quantity) FROM inventory_items').then(r => r.rows[0].sum),
    inventoryDb.query('SELECT SUM(quantity) FROM inventory_items').then(r => r.rows[0].sum)
  ]);
  const matches = Math.abs(oldTotal - newTotal) < 1; // within 1 unit
  if (!matches) logger.error({ oldTotal, newTotal }, 'Inventory migration diverged!');
  return matches;
}

